  add('flower','basic','花の外側にあって、つぼみのとき、花全体をまもる部分を何といいますか。','がく',['おしべ','めしべ','子房'],['花びらの外側についています。','つぼみのときは花びらをつつんでいます。'],'がくはつぼみのとき、花全体をまもる部分です。', {"kind":"biology","part":"flower","labels":["","","","エ"],"focus":"outside","caption":"花の外側の部分を記号で示した模式図","study":true});
  add('flower','basic','ヘチマの花のうち受粉したあとに実ができるのはどちらですか。','めばな',['おばな','どちらもできる','どちらもできない'],['めしべがある花です。','子房がある花です。'],'ヘチマにはおばなとめばなの２種類があります。実ができるのはめしべのあるめばなです。');
  add('flower','basic','アサガオの１つの花には、おしべとめしべがどのようについていますか。','１つの花に両方ついている',['おしべだけついている','めしべだけついている','どちらもついていない'],['アサガオの花をよく見てみましょう。','ヘチマとはちがいます。'],'アサガオは１つの花におしべとめしべの両方があります。');

  add('flower','standard','ヘチマのおばなには何がありますか。','おしべがある（めしべはない）',['めしべがある（おしべはない）','おしべもめしべもある','おしべもめしべもない'],['おばなは花粉をつくる花です。','めばなとのちがいを考えましょう。'],'おばなにはおしべがありますがめしべがありません。花粉をつくります。');
  add('flower','standard','ヘチマのめばなには何がありますか。','めしべがある（おしべはない）',['おしべがある（めしべはない）','おしべもめしべもある','おしべもめしべもない'],['実になる花はどちらでしょう。','おばなとのちがいを考えましょう。'],'めばなにはめしべがありますがおしべがありません。受粉すると実ができます。');
  add('flower','standard','受粉しなかっためばなはどうなりますか。','実ができずに、かれて落ちる',['実が大きく育つ','種子だけできる','別の花になる'],['実ができるには何が必要でしたか。','受粉しないと子房は大きくなりません。'],'受粉しなかっためばなは、実ができずに、かれて落ちてしまいます。');
  add('flower','standard','めばなのつぼみにふくろをかけておくのは、何のためですか。','虫や風がほかの花粉を運んでくるのをふせぐため',['花をあたためるため','花に水をあたえるため','虫に花を見せるため'],['花粉が自然につくのをふせぎます。','受粉をさせるかさせないかを決めたいからです。'],'ふくろをかけると、虫や風が花粉を運んでくるのをふせげます。受粉の有無を自分で決められます。');
  add('flower','standard','受粉がすんだあとアサガオの花びらはどうなりますか。','しおれて落ちる',['大きくなる','色がこくなる','実になる'],['花びらは花粉を運ぶ虫をよぶものです。','受粉したあとは役目をおえます。'],'受粉がすんだあと花びらはしおれて落ちます。');
  add('flower','standard','受粉がすんだあと子房はどうなりますか。','大きくなって実になる',['小さくなってなくなる','色がかわって花びらになる','そのままかわらない'],['子房はめしべのもとの部分です。','中に種子ができます。'],'受粉のあと子房は大きくなり実になります。実の中には種子ができます。');
  add('flower','standard','種子ができるために必要なことは何ですか。','受粉',['発芽','光合成','開花だけ'],['おしべとめしべが関係します。','花粉がめしべの先につくことです。'],'種子ができるには受粉が必要です。');
  add('flower','standard','マツやトウモロコシは、おもに何によって、花粉を運んでもらいますか。','風',['虫','鳥','水'],['花粉はとても軽くて小さいです。','虫をよぶあざやかな花びらはありません。'],'マツやトウモロコシなどは、風によって花粉が運ばれます。');
  add('flower','standard','虫に花粉を運んでもらう花に多く見られる特ちょうはどれですか。','色があざやかでみつがある',['色が地味でにおいもない','花粉がとても軽い','花びらがない'],['虫はみつをすいに来ます。','虫をよびよせる工夫があります。'],'虫に花粉を運んでもらう花は、あざやかな色の花びらやみつなどで虫をよびよせます。');
  add('flower','standard','花粉をくわしく観察するときに使う器具は、何ですか。','けんび鏡',['虫めがね','ビーカー','顕微鏡ではなく望遠鏡'],['花粉はとても小さいものです。','倍率を変えられる道具です。'],'花粉のような小さなものは、けんび鏡で観察します。', {"kind":"apparatus","panels":[{"tool":"microscope","labels":["ア","イ","ウ"]}],"caption":"観察に使う器具の模式図。部分は記号だけで示している","study":true});
  add('flower','standard','けんび鏡で接眼レンズが10倍対物レンズが40倍のとき、全体の倍率は何倍ですか。',400,[50,100,4000],['接眼レンズの倍率と対物レンズの倍率をかけます。','10 × 40 を計算しましょう。'],'けんび鏡の倍率は接眼レンズの倍率 × 対物レンズの倍率です。10 × 40 = 400（倍）です。', {"kind":"apparatus","panels":[{"tool":"microscope","magnifications":[10,40]}],"caption":"二つのレンズの倍率。全体の倍率は示していない","study":true});
  add('flower','standard','けんび鏡を使うとき、はじめにどの倍率にしますか。','いちばん低い倍率',['いちばん高い倍率','どの倍率でもよい','中くらいの倍率'],['はじめは広い範囲を見ます。','見つけてから倍率をあげます。'],'けんび鏡は広い範囲を見やすいいちばん低い倍率から使いはじめます。');
  add('flower','standard','いろいろな植物の花粉をけんび鏡で見ると、花粉の形はどうなっていますか。','植物によって形がちがう',['どの植物も同じ形','すべてまるい形','すべて四角い形'],['アサガオ・ヘチマ・マツなどを見くらべます。','花粉の形に特ちょうがあります。'],'花粉の形や大きさは植物の種類によって、ちがいます。');
  add('flower','standard','花粉をつくるおしべの先の部分を何といいますか。','やく',['がく','柱頭','子房'],['おしべの先にあります。','花粉はここにつまっています。'],'おしべの先の花粉をつくる部分をやくといいます。', {"kind":"biology","part":"stamen","labels":["ア"],"caption":"花の一つの部分を大きくした模式図。名前は示していない","study":true});
  add('flower','standard','花から実ができるまでの順番として正しいのはどれですか。','花がさく → 受粉 → 子房がふくらむ → 実ができる',['受粉 → 花がさく → 実ができる → 子房がふくらむ','実ができる → 受粉 → 花がさく','子房がふくらむ → 花がさく → 受粉'],['まず花がさかないと受粉はできません。','最後に実ができます。'],'花がさいて受粉し子房がふくらんで実ができます。');

  add('flower','advanced','めばなのつぼみにふくろをかけ花がさいたあとにおしべの花粉をつけた花とつけなかった花で実ができるのはどちらですか。','花粉をつけた花',['花粉をつけなかった花','どちらもできる','どちらもできない'],['実ができるには何が必要でしたか。','ふくろをかけて虫や風をふせいでいます。'],'受粉した花だけが実をつくります。花粉をつけなかった花は、実ができません。');
  add('flower','advanced','つぼみにふくろをかけたまま花がさいても、実ができませんでした。その理由は何ですか。','受粉しなかったから',['花粉がつきすぎたから','水が足りなかったから','日光に当たりすぎたから'],['ふくろの中には虫や風が入れません。','実ができる条件を考えましょう。'],'ふくろの中では虫や風が花粉を運べず受粉しないので、実ができません。');
  add('flower','advanced','虫のいない部屋でカボチャを育てると、実ができにくくなります。その理由は何ですか。','花粉を運ぶ虫がいなくて、受粉しにくいから',['日光が足りないから','肥料が足りないから','水が多すぎるから'],['カボチャは虫に花粉を運んでもらう花です。','部屋の中には虫がいません。'],'カボチャは虫が花粉を運びます。虫がいないと受粉しにくく実ができにくくなります。');
  add('flower','advanced','ヘチマのおばなを全部取りのぞくと、めばなにはどんなことが起こりますか。','花粉が手に入らず受粉しにくくなる',['実が大きくなる','種子が増える','花がたくさんさく'],['花粉はどちらの花でつくられますか。','おばなの役目を考えましょう。'],'花粉をつくるのはおばなです。おばなを取りのぞくと、めばなは受粉しにくく実ができにくくなります。');
  add('flower','advanced','めしべがなくおしべだけの花があります。この花から実はできますか。','できない',['できる','種子だけできる','おしべが実になる'],['実になる部分はめしべのもとです。','めしべがないとどうなるでしょう。'],'めしべがないと子房がないので、実はできません。');
  add('flower','advanced','めしべはありますが花粉がつかなかった花は、どうなりますか。','実ができない',['実ができる','かならず種子ができる','おしべになる'],['実になる条件は受粉です。','花粉がつかないとどうなるでしょう。'],'めしべに花粉がつかないと受粉しないので、実ができません。');
  add('flower','advanced','花粉は同じ花のめしべだけでなくほかの花のめしべにつくこともあります。この場合も実はできますか。','できる',['できない','種子だけできる','花びらだけできる'],['受粉とはめしべに花粉がつくことです。','どの花の花粉かは問いません。'],'同じ種類の植物であれば、ほかの花の花粉がめしべについても、受粉して実ができます。');
  add('flower','advanced','受粉してできた種子は、どんな役目がありますか。','次の世代の植物になる',['実を重くする','花びらを守る','根をはらせる'],['種子はまくと発芽します。','植物がなかまを増やすためにつくります。'],'種子はまくと発芽して、新しい植物になります。植物のなかまを増やす役目があります。');
  add('flower','advanced','受粉に関する説明として、正しいものはどれですか。','花粉がめしべの先につくこと',['めしべの花粉がおしべにつくこと','種子が発芽すること','花びらが落ちること'],['おしべでつくられたものが、めしべにつきます。','先にねばねばした部分があります。'],'受粉とはおしべでつくられた花粉が、めしべの先につくことです。');
  add('flower','advanced','アサガオがつぼみのころにすでに受粉することがあります。その理由は何ですか。','おしべとめしべが同じ花の中にあり近いから',['虫がつぼみの中に入るから','風がつぼみを開けるから','花粉が水で運ばれるから'],['アサガオは一つの花に両方があります。','おしべとめしべは近くにあります。'],'アサガオは一つの花の中におしべとめしべがあり近いのでつぼみのうちに受粉することもあります。');
  add('flower','advanced','ヘチマでおばなとめばなの数を数えました。実になる花の数はおもに何でわかりますか。','めばなの数',['おばなの数','花びらの数','葉の数'],['実ができるのはどちらの花でしたか。','めしべがある花です。'],'実になるのはめばなだけです。めばなの数がわかれば、実の数の目安になります。');
  add('flower','advanced','花から実ができたとき、実の中にできる種子の数を決めるのは、おもに何ですか。','受粉できた子房の中の小さな粒の数',['おしべの数','花びらの数','葉の数'],['子房の中には将来種子になる粒があります。','受粉するとそれが種子になります。'],'子房の中に種子になる粒があり受粉したものが種子になります。');

  // ---- 動物の誕生（メダカ・人）：基礎9・標準15・発展12 ----
  add('life','basic','メダカのたまごをうむのはおすとめすのどちらですか。','めす',['おす','どちらも','どちらでもない'],['めすのおなかはふくらんでいます。','おすは精子をつくります。'],'たまご（卵）をうむのは、めすです。おすは精子をつくります。');
  add('life','basic','めすのメダカのしりびれの形はどうなっていますか。','三角形で小さい',['平行四辺形で大きい','しりびれがない','まるい形'],['おすのしりびれとは形がちがいます。','おすは平行四辺形で大きいです。'],'めすのしりびれはおすより小さくて、三角形に近い形です。');
  add('life','basic','おすのメダカのせびれはどうなっていますか。','切れこみがある',['切れこみがない','せびれがない','ひれがとても大きい'],['めすとのちがいを考えます。','めすには切れこみがありません。'],'おすのせびれには切れこみがあります。めすには切れこみがありません。');
  add('life','basic','メダカのめすがうんだ卵とおすの出した精子が結びつくことを何といいますか。','受精',['受粉','発芽','成長'],['精子と卵がいっしょになることです。','結びつくと成長がはじまります。'],'卵と精子が結びつくことを受精といいます。',null,['じゅせい','受精']);
  add('life','basic','受精した卵を何といいますか。','受精卵',['精子','受粉卵','種子'],['卵と精子が結びついたものです。','成長して子メダカになります。'],'受精した卵を受精卵といいます。',null,['じゅせいらん','受精卵']);
  add('life','basic','メダカを飼うとき、水そうを置く場所として、よいのはどこですか。','直射日光の当たらない明るい所',['直射日光がよく当たる所','真っ暗な所','風がよく当たる所'],['日光が強すぎると、水の温度が上がりすぎます。','暗すぎるのもよくありません。'],'直射日光が当たると水温が上がりすぎるので、当たらない明るい所に置きます。');
  add('life','basic','メダカの卵はおおよそ何日で子メダカがかえりますか（水温25℃くらい）。','約11日',['約1日','約3日','約30日'],['気温の高い夏でもすぐにはかえりません。','約10日くらいです。'],'メダカの卵は水温25℃くらいで約11日でかえります。');
  add('life','basic','かえったばかりのメダカの子は、はらにふくろをつけています。このふくろには何が入っていますか。','養分',['空気','水','たまご'],['数日はえさを食べなくても生きていけます。','はらのふくろはだんだん小さくなります。'],'かえったばかりの子メダカは、はらのふくろの養分で数日間育ちます。');
  add('life','basic','メダカのおすとめすを見分けるときに見るのはどこですか。','せびれとしりびれ',['目の大きさ','体の色','口の形'],['ひれの形がちがいます。','めすとおすではひれの形がちがいます。'],'おすとめすはせびれとしりびれの形で見分けます。');

  add('life','standard','人の卵（卵子）と精子が結びつくことを何といいますか。','受精',['受粉','発芽','誕生'],['メダカの卵と精子と同じです。','結びつくと新しい命がはじまります。'],'人も卵と精子が結びつくこと（受精）から命がはじまります。',null,['じゅせい','受精']);
  add('life','standard','人の受精卵が育つのは母親の体のどこですか。','子宮',['胃','小腸','肺'],['生まれる前の赤ちゃんが育つ場所です。','おなかの中にあります。'],'受精卵は母親の子宮の中で育ちます。', {"kind":"biology","part":"pregnancy","labels":["ア","イ","ウ","エ"],"caption":"体内の断面の模式図。記号は部分の位置を示している","study":true},['しきゅう','子宮']);
  add('life','standard','子宮の中で赤ちゃんを守っている液体は何ですか。','羊水',['血液','だ液','胃液'],['赤ちゃんはこの液体の中に浮かんでいます。','外からのしょうげきをやわらげます。'],'子宮の中の赤ちゃんは、羊水に浮かんでいて、しょうげきから守られています。', {"kind":"biology","part":"pregnancy","labels":["ア","イ","ウ","エ"],"caption":"体内の断面の模式図。記号は部分の位置を示している","study":true},['ようすい','羊水']);
  add('life','standard','胎児が母親から養分や酸素をもらうときに通る管を何といいますか。','へそのお（へその緒）',['食道','気管','血管だけ'],['生まれたあと、おなかのまん中にあとが残ります。','母親とつながる管です。'],'胎児はへその緒を通して、母親から養分や酸素をもらいいらないものをわたします。', {"kind":"biology","part":"pregnancy","labels":["ア","イ","ウ","エ"],"caption":"体内の断面の模式図。記号は部分の位置を示している","study":true},['へその緒','へそのお','臍の緒']);
  add('life','standard','母親の体内で胎児と母親の血液が物質をやりとりする部分を何といいますか。','胎盤',['胃','子宮頸','肝臓'],['子宮のかべにあります。','へその緒とつながっています。'],'胎盤では母親から胎児へ養分や酸素が、胎児から母親へいらないものがわたされます。', {"kind":"biology","part":"pregnancy","labels":["ア","イ","ウ","エ"],"caption":"体内の断面の模式図。記号は部分の位置を示している","study":true},['たいばん','胎盤']);
  add('life','standard','人の受精卵が母親の体内で育って、生まれるまでの期間は、およそどのくらいですか。','約38週（約9か月）',['約3週','約3か月','約2年'],['１年はかかりません。','およそ９か月です。'],'人は約38週（およそ９か月）母親の体内で育ってから生まれます。');
  add('life','standard','生まれたばかりの赤ちゃんの体重は、およそどのくらいですか。','約3000g',['約300g','約30000g','約300000g'],['およそ３kgです。','お米の袋（5kg）より軽いです。'],'生まれたばかりの赤ちゃんの体重は、約3000g（約3kg）です。');
  add('life','standard','生まれたばかりの赤ちゃんの身長は、およそどのくらいですか。','約50cm',['約5cm','約150cm','約500cm'],['およそ50cmです。','ものさし１本分くらいです。'],'生まれたばかりの赤ちゃんの身長は、約50cmです。');
  add('life','standard','人の赤ちゃんが母親の体内でおなかの外とちがうのは、何ですか。','母親から養分や酸素をもらっている',['自分でえさを食べている','肺で呼吸している','自分の力で動き回っている'],['へその緒でつながっています。','生まれる前の赤ちゃんは、口からはえさを食べません。'],'胎児はへその緒を通して、母親から養分や酸素をもらっています。');
  add('life','standard','メダカを飼う水そうに水草を入れる理由として、正しいものはどれですか。','卵をうみつけやすくするため',['メダカをさむくするため','えさの代わりにするため','水をにごらせるため'],['メダカのめすは水草に卵をうみつけます。','水草は酸素をつくる働きもします。'],'メダカのめすは卵を水草につけるようにうみます。水草があると、卵をうみつけやすくなります。');
  add('life','standard','けんび鏡でメダカの卵の中を日がたつごとに観察すると、体のどんな部分が見えるようになりますか。','目や心ぞうなど体のつくりがだんだんできる',['何も見えない','殻だけが厚くなる','水だけが増える'],['卵の中で子メダカの体がつくられていきます。','透明な卵なので、中が見えます。'],'卵が育つにつれて、目や心ぞう血管などの体のつくりが、しだいにできてきます。');
  add('life','standard','メダカの卵と人の卵では大きさが大きいのはどちらですか。','メダカの卵',['人の卵','どちらも同じ','どちらもとても大きい'],['人の卵はとても小さく直径約0.14mmです。','メダカの卵は約1mmです。'],'メダカの卵は直径約1mmで人の卵（約0.14mm）より大きいです。');
  add('life','standard','人のように母親の体内で子が育ってから生まれるうまれ方を何といいますか。','胎生',['卵生','変態','受粉'],['メダカのように、卵をうむものは卵生です。','子の形で生まれるうまれ方です。'],'母親の体内である程度育ってから子の姿で生まれるうまれ方を胎生といいます。',null,['たいせい','胎生']);
  add('life','standard','メダカの受精卵が育つときの養分は何からもらいますか。','卵の中にある養分',['母親の体','水の中の養分','えさ'],['メダカの卵は水の中にうみ出されます。','卵の中にあらかじめ養分があります。'],'メダカの受精卵は卵の中の養分で育ちます。母親の体から養分をもらう人とは、ちがいます。');
  add('life','standard','人の受精卵とメダカの受精卵の育つ場所のちがいは何ですか。','人は母親の体内メダカは体の外（水の中）',['人は水の中メダカは母親の体内','どちらも母親の体内','どちらも水の中'],['メダカは卵をうみます。','人は子を産みます。'],'人の受精卵は母親の体内で育ちます。メダカの受精卵はうみ出されたあと、水の中で育ちます。');

  add('life','advanced','おすとめすをいっしょに飼った水そうの卵だけが、かえりました。その理由は何ですか。','受精した卵だけが成長するから',['おすが卵をあたためたから','めすが卵を食べなかったから','水そうが広かったから'],['卵が成長するには受精が必要です。','おすがいないと精子がありません。'],'卵は受精すると成長がはじまります。おすがいないと受精しないので、卵はかえりません。');
  add('life','advanced','メダカの卵がうまれてもかえらずに白くにごってしまいました。考えられる理由は何ですか。','受精していなかったから',['水温が高すぎたから','日光が弱かったから','水草が多かったから'],['受精卵は成長します。','受精しなかった卵はどうなるでしょう。'],'受精していない卵は成長せずやがて白くにごってしまいます。');
  add('life','advanced','メダカの卵を水温が低い（15℃くらいの）水の中で育てると、かえるまでの日数はどうなりますか。','長くなる',['短くなる','かわらない','かえらなくなる（かならず）'],['水温が25℃のときは、約11日でかえります。','水温が低いと成長のスピードがどうなりますか。'],'水温が低いと卵の成長がおそくなるので、かえるまでの日数は長くなります。');
  add('life','advanced','メダカの子がかえった直後はえさをあたえなくてもよいのは、なぜですか。','はらのふくろに養分があるから',['えさを食べなくても生きられるから','水の中にえさがあるから','親がえさをあたえるから'],['かえったばかりの子メダカをよく見てみましょう。','はらにふくろがついています。'],'かえった直後の子メダカは、はらのふくろの養分で数日間育ちます。');
  add('life','advanced','人の赤ちゃんが生まれたあと、母親から養分をもらう方法はどうなりますか。','母乳（ミルク）を口から飲む',['へその緒からもらいつづける','胎盤からもらいつづける','自分で食べものをさがす'],['生まれるとへその緒は切られます。','しばらくは母乳やミルクで育ちます。'],'生まれたあとの赤ちゃんは、へその緒ではなく母乳やミルクを口から飲んで養分をとります。');
  add('life','advanced','受精卵が育って人の赤ちゃんになるまでの順番として、正しいものはどれですか。','受精卵 → 子宮の中で成長 → 約38週 → 誕生',['誕生 → 受精卵 → 子宮の中で成長','子宮の中で成長 → 受精卵 → 誕生','誕生 → 成長 → 受精卵'],['まず卵と精子が受精します。','最後に赤ちゃんが生まれます。'],'卵と精子が受精して、受精卵ができ子宮の中で約38週育ってから生まれます。');
  add('life','advanced','人の精子と卵では大きいほうはどちらですか。','卵（卵子）',['精子','どちらも同じ','どちらもとても大きい'],['精子は長いしっぽで泳ぎます。','卵のほうは動かず大きいです。'],'卵（卵子）は精子より大きく直径約0.14mmです。精子は約0.06mmです。');
  add('life','advanced','メダカのおすがめすの近くを泳ぎまわるのは何のためですか。','受精のため（子孫を残すため）',['えさをとるため','たいようの光を浴びるため','空気を吸うため'],['めすが卵をうむとき、おすが精子をかけます。','メダカはなかまを増やします。'],'おすがめすの近くを泳ぐのは、めすがうんだ卵に精子をかけて、受精させるためです。');
  add('life','advanced','メダカが卵をうむのにひれが関係している点として、正しいものはどれですか。','おすはしりびれでめすの卵を包むようにして、受精させる',['めすがせびれで卵をうむ','おすがむなびれで卵をうむ','ひれは卵とは関係がない'],['おすのしりびれは大きくて平行四辺形です。','受精のとき、おすのひれが役立ちます。'],'おすのしりびれは大きく受精のときめすの卵を包むようにして使われます。');
  add('life','advanced','人の胎児が母親のおなかの中で呼吸しなくてもよいのは、なぜですか。','へその緒を通して、母親から酸素をもらっているから',['水の中だから','肺で空気を吸っているから','酸素がいらないから'],['胎児は生まれる前は肺で呼吸していません。','母親の血液から酸素をもらっています。'],'胎児は生まれる前は肺で呼吸せずへその緒を通して、母親から酸素をもらっています。');
  add('life','advanced','メダカの卵と人の卵の育ち方のちがいとして、正しいものはどれですか。','メダカは卵のまま育つ（卵生）人は子宮で育つ（胎生）',['どちらも卵のまま育つ','どちらも子宮で育つ','メダカは子宮人は卵のまま育つ'],['メダカは卵をうみます。','人は子を産みます。'],'メダカは卵のまま水の中で育つ「卵生」、人は母親の子宮で育つ「胎生」です。');
  add('life','advanced','生き物が卵と精子による受精で子をつくるのはどんな意味がありますか。','親とはちがういろいろな性質の子ができる',['親とまったく同じ子が生まれる','子がすぐに大人になる','卵が多くなる'],['両親からいろいろなものを受けつぎます。','兄弟でも少しずつちがいます。'],'卵と精子が結びつくと、両方の親の性質を受けついだ新しい命ができます。');

  // ---- 天気の変化と台風：基礎9・標準15・発展12 ----
  add('weather','basic','空全体の広さを10としたとき、雲の量が５のときの天気は何ですか。','晴れ',['くもり','雨','快晴'],['雲の量が０〜８のときは晴れです。','雲の量が９〜10のときは、くもりです。'],'雲の量が０〜８のときは晴れ９〜10のときはくもりです。雲の量が５のときは晴れです。', {"kind":"scienceScene","scene":"cloudCover","total":10,"covered":5,"caption":"空を同じ大きさの十ますに分けた図。天気の名前は示していない","study":true});
  add('weather','basic','空全体の広さを10としたとき、雲の量が９のときの天気は何ですか。','くもり',['晴れ','雨','快晴'],['雲の量が９〜10のときは、くもりです。','雲の量が０〜８のときは晴れです。'],'雲の量が９〜10のときは、くもりです。', {"kind":"scienceScene","scene":"cloudCover","total":10,"covered":9,"caption":"空を同じ大きさの十ますに分けた図。天気の名前は示していない","study":true});
  add('weather','basic','夏の午後などにせまい範囲にはげしい雨やかみなりをもたらすもくもくと高くのびた雲を何といいますか。','積乱雲（入道雲）',['すじ雲','うろこ雲','わた雲だけ'],['かみなりをともなうことも多い雲です。','「入道雲」ともよばれます。'],'積乱雲（入道雲）は夏の午後にはげしい雨やかみなりをもたらすことがあります。');
  add('weather','basic','日本付近では雲や天気はふつうどの方向に動いていくことが多いですか。','西から東',['東から西','南から北','北から南'],['日本の上空には西から東へふく風があります。','天気は西から変わってきます。'],'日本付近では雲や天気は西から東へ動くことが多いです。');
  add('weather','basic','雲の動きを宇宙から観測している人工衛星を何といいますか。','気象衛星（ひまわり）',['通信衛星','月の衛星','ロケット'],['雲画像はテレビの天気予報でも使われます。','「ひまわり」という名前の衛星が有名です。'],'気象衛星（ひまわり）は、宇宙から雲のようすを観測しています。');
  add('weather','basic','雨や風気温などを全国のたくさんの場所で自動的に観測するしくみを何といいますか。','アメダス',['ひまわり','ナビ','テレビ'],['日本全国の1300か所ほどに観測所があります。','正式には「地域気象観測システム」です。'],'アメダスは雨・風・気温などを全国で自動的に観測するしくみです。');
  add('weather','basic','台風はどこで生まれますか。','熱帯の海の上',['北極の海','日本の山の中','砂ばくの上'],['あたたかい海で水蒸気がたくさん出ます。','赤道に近い海です。'],'台風はあたたかい熱帯の海の上で生まれます。');
  add('weather','basic','台風が近づくと、どのような天気になりますか。','強い風とはげしい雨',['おだやかな晴れ','弱い雨だけ','雪'],['台風は大きな雲のうずです。','風も雨も強くなります。'],'台風が近づくと、強い風とはげしい雨になり災害が起こることがあります。');
  add('weather','basic','台風が日本に近づくことが、もっとも多い季節はいつですか。','夏から秋',['春から夏','秋から冬','冬から春'],['海水があたたかくなる季節です。','８月〜９月に多いです。'],'台風は海水があたたかくなる夏から秋に日本に近づくことが多いです。');

  add('weather','standard','台風が日本付近に来るとき、はじめは北西に進みのちに東へ向きを変えることが多いのは、なぜですか。','上空の西風（偏西風）にふかれるから',['地球の自転が止まるから','北から強い風がふくから','太陽の光が当たるから'],['日本の上空には西から東へふく風があります。','台風はその風に流されます。'],'日本付近の上空には西から東へふく風（偏西風）があり台風はその風に流されて、東へ向きを変えます。', {"kind":"scienceScene","scene":"cloudMap","track":[[235,285],[175,235],[145,170],[205,115],[305,80]],"trackLabels":["ア","イ"],"caption":"台風のはじめとあとの位置を点線で示した模式図","study":true});
  add('weather','standard','台風の中心付近で風が弱く雲が少ない部分を何といいますか。','台風の目',['台風の口','台風の耳','台風の足'],['台風の中心にあるぽっかりあいた部分です。','雨や風が弱くなることがあります。'],'台風の中心付近には風が弱く雲の少ない「台風の目」があります。', {"kind":"scienceScene","scene":"typhoon","labels":["ア","イ"],"caption":"上から見た図と断面の模式図。部分の名前は示していない","study":true});
  add('weather','standard','台風がもたらす被害として、まちがっているものはどれですか。','かんばつ（雨がまったくふらない）',['強風による木や家のたおれ','大雨による川のこう水','土砂くずれ'],['台風はたくさんの雨と風をもたらします。','台風の被害には水に関するものが多いです。'],'台風は強い風や大雨でこう水や土砂くずれなどの被害をもたらします。雨がまったくふらないかんばつは、台風の被害ではありません。');
  add('weather','standard','台風がもたらすよいえいきょうとして、あげられるものはどれですか。','ダムに水がたまり水不足がかいしょうされる',['ねっ帯夜が増える','雪がたくさんふる','かんばつが起こる'],['台風はたくさんの雨をふらせます。','雨が少ない地域では助かる場合もあります。'],'台風の大雨でダムに水がたまり水不足がかいしょうされることもあります。');
  add('weather','standard','春や秋に西の地方で雨がふっていたとき、数時間から半日後の東の地方の天気はどうなる可能性が高いですか。','雨がふる可能性が高い',['雨がふらない','晴れつづける','雪になる'],['雲は西から東へ動きます。','西にある雲が東へやって来ます。'],'雲は西から東へ動くので、西で雨が降っているときは、あとから東でも雨がふる可能性が高くなります。');
  add('weather','standard','雨をふらせる厚い雲を何といいますか。','乱層雲（雨雲）',['巻雲（すじ雲）','積雲（わた雲）','巻積雲（うろこ雲）'],['空全体を厚くおおうような雲です。','しとしとと長くふる雨をもたらします。'],'乱層雲（雨雲）は空をおおって長い時間雨をふらせます。');
  add('weather','standard','晴れの日に空にぽっかりうかぶ白いわたのような雲を何といいますか。','積雲（わた雲）',['乱層雲','積乱雲','層雲'],['天気がよいときに見られます。','わたがうかんでいるような形の雲です。'],'積雲（わた雲）は晴れた日に見られるわたのような雲です。');
  add('weather','standard','雲画像で日本の西側に大きな雲のかたまりがあります。次の日の日本の天気は、どうなる可能性が高いですか。','雲がやってきてくもりや雨になる',['晴れがつづく','雪になる','台風が消える'],['雲は西から東へ動きます。','雲画像から天気を予想できます。'],'西の雲は東へ動いて日本に近づくので、くもりや雨になる可能性が高くなります。', {"kind":"scienceScene","scene":"cloudMap","westCloud":true,"caption":"雲画像の模式図。次の日のようすは示していない","study":true});
  add('weather','standard','6月から７月ごろ日本でくもりや雨の日がつづく時期を何といいますか。','梅雨（つゆ）',['台風','かんばつ','小春日和'],['雨がつづくむしむしした時期です。','「ばいう」とも読みます。'],'6月から7月ごろくもりや雨の日がつづく時期を梅雨（つゆ）といいます。',null,['つゆ','梅雨','ばいう']);
  add('weather','standard','雨量を表す単位は何ですか。','mm（ミリメートル）',['g','℃','m/s'],['雨が地面にたまったときの水の深さで表します。','雨量計ではかります。'],'雨量は降った雨がたまったときの深さを表すmm（ミリメートル）で表します。');
  add('weather','standard','台風の進路を予想するのに役立つものは何ですか。','気象衛星の雲画像',['地図帳','かがみ','地球ぎ'],['雲の動きがわかる画像です。','宇宙から台風を観測しています。'],'気象衛星の雲画像で台風の位置や動きがわかり進路の予想に役立ちます。');
  add('weather','standard','台風が近づく前にしてはいけないことは何ですか。','川や海のようすを見に行く',['避難場所をたしかめる','家の窓をしっかりしめる','天気予報を見る'],['台風のときはあぶないことがあります。','川の水かさは急に増えることがあります。'],'台風のときに川や海を見に行くのは、とてもきけんです。安全な場所でじっとしていましょう。');
  add('weather','standard','雲の量を決めるときの観察の方法として、正しいものはどれですか。','空全体を見て雲がしめる広さを10分のいくつか調べる',['空の一部だけを見る','雲の高さだけを調べる','雲の色だけを調べる'],['空全体の広さを10としたとき、考えます。','一部だけでは全体がわかりません。'],'空全体を10としたとき、雲がしめる広さがいくつにあたるかで雲の量を決めます。');

  add('weather','advanced','雲画像とアメダスの雨量情報を合わせると、どんなことがわかりますか。','雲の動きと実際にふった雨の量',['月の満ち欠け','星の色','海の深さ'],['雲画像は雲の動きをアメダスは雨量などを観測します。','両方を使うと、天気の変化がよりくわしくわかります。'],'雲画像で雲の動きがわかりアメダスで実際にふった雨の量などがわかります。合わせて天気の予想に役立ちます。');
  add('weather','advanced','日本付近で天気が西から東へ変わっていくおもな理由は何ですか。','上空に西から東へふく風（偏西風）があるから',['地球が東から西へ回っているから','月の引力があるから','海流が東へ流れているから'],['雲は上空の風に流されて動きます。','日本の上空では西から東へ風がふいています。'],'日本付近の上空には西から東へふく風（偏西風）があり雲や天気はその風によって東へ動きます。');
  add('weather','advanced','台風が南の海から北のほうへ進むにつれて、勢力が弱まることが多いのは、なぜですか。','海水の温度が低くなり水蒸気の補給が少なくなるから',['太陽の光が弱まるから','風がやむから','月が出てくるから'],['台風はあたたかい海から水蒸気をもらって、育ちます。','北へ行くと海水の温度はどうなるでしょう。'],'台風はあたたかい海の水蒸気をエネルギーにしています。北へ進むと海水の温度が低くなって、勢力が弱まります。');
  add('weather','advanced','台風が通過したあと、川の水が増えてこう水が起こるのはなぜですか。','大雨で水が一度に川に流れこむから',['台風が水を運んでくるから','台風が川の水をあたためるから','台風が水をなくすから'],['台風は大量の雨をふらせます。','山や道に降った雨は川に集まります。'],'台風の大雨でたくさんの雨水が川に一度に流れこむと、川の水が増えてこう水が起こりやすくなります。');
  add('weather','advanced','雲の量が空全体の10分の８で雨がふっていません。このときの天気は何ですか。','晴れ',['くもり','雨','快晴'],['雲の量が９以上のときが、くもりです。','雲の量が０〜８のときは、晴れです。'],'雲の量が８のときは晴れです。９以上になると、くもりです。', {"kind":"scienceScene","scene":"cloudCover","total":10,"covered":8,"caption":"空を同じ大きさの十ますに分けた図。雨は描いていない","study":true});
  add('weather','advanced','台風が日本付近で速度を上げて東へ進むのはおもに何の影響ですか。','上空の強い西風（偏西風）',['台風の中の気温','海の波','太陽の高さ'],['台風は上空の風に流されます。','日本付近では上空の風が強いです。'],'台風は日本付近で上空の強い西風（偏西風）に流されて、速度を上げて東へ進むことがあります。');
  add('weather','advanced','天気予報がまちがうことがあるのは、なぜですか。','自然はとても複雑で完全には予測できないから',['天気はまったくの運だから','気象衛星が役に立たないから','予報士がでたらめを言うから'],['天気はたくさんの要素で決まります。','予報はあくまで予想です。'],'天気はたくさんの要素が関係しとても複雑なので、完全には予測できず予報が外れることもあります。');
