  add('pendulum','standard','10往復の時間が20秒でした。ふりこの周期は何秒ですか。','2',['20','200','0.2'],['10往復の時間を10でわります。','20 ÷ 10 を計算しましょう。'],'1往復の時間は 20 ÷ 10 = 2（秒）です。',null,true);
  add('pendulum','standard','ふりこの長さを短くしました。周期はどうなりますか。','短くなる',['長くなる','変わらない','2倍になる'],['短いほど速くゆれます。','長さが短いほど1往復の時間が短くなります。'],'ふりこの長さが短いほど周期は短くなります。');
  add('pendulum','standard','ふりこの長さが同じでおもりの重さがちがう2つのふりこをふらせました。周期はどうなりますか。','同じになる',['重いほうが長い','軽いほうが長い','重いほうが止まる'],['周期は重さに関係しません。','長さが同じなら周期も同じです。'],'周期はふりこの長さだけで決まるので、重さがちがっても同じです。', {"kind":"pendulum","panels":[{"mode":"compare","label":"Ａ","size":16},{"mode":"compare","label":"Ｂ","size":26}],"caption":"糸の長さが同じで、おもりがちがう二つのふりこ","study":true});
  add('pendulum','standard','ふりこの長さが同じでふれはばがちがう2つのふりこをふらせました。周期はどうなりますか。','同じになる',['ふれはばが大きいほうが長い','ふれはばが小さいほうが長い','一方が止まる'],['ふれはばは周期に関係しません。','長さが同じなら周期も同じです。'],'ふれはばを変えても周期は変わらないので、周期は同じです。', {"kind":"pendulum","panels":[{"mode":"amplitude","label":"Ａ","angle":15},{"mode":"amplitude","label":"Ｂ","angle":35}],"caption":"糸とおもりは同じ。ふれはばだけを変えた模式図","study":true});
  add('pendulum','standard','ふりこが一番低い位置を通るとき、おもりの速さはどうなっていますか。','一番速い',['一番おそい','止まっている','変わらない'],['いちばん低いところでは、勢いがついています。','はしでは一瞬止まります。'],'ふりこは一番低い位置で最も速くふれはばの両はしで一瞬止まります。', {"kind":"pendulum","panels":[{"mode":"positions","labels":["","ア",""]}],"caption":"記号は一番低い位置。速さは示していない","study":true});
  add('pendulum','standard','ふりこがふれはばの両はしにきたとき、おもりの速さはどうなっていますか。','一瞬止まる',['一番速い','変わらない','だんだん速くなる'],['向きが変わるところです。','行ったあともどりはじめます。'],'ふれはばの両はしでは、向きが変わるために一瞬止まります。', {"kind":"pendulum","panels":[{"mode":"positions","labels":["ア","","イ"]}],"caption":"記号は両はしの位置。速さは示していない","study":true});
  add('pendulum','standard','ふりこを長い時間ふらせつづけると、ふれはばはどうなりますか。','だんだん小さくなる',['だんだん大きくなる','変わらない','急に2倍になる'],['空気の力や糸のまさつがはたらきます。','少しずつ止まっていきます。'],'空気の抵抗などでふれはばはだんだん小さくなりやがて止まります。');
  add('pendulum','standard','ふりこの実験でおもりを何個かつけて重さを変えるとき、変わらないのは何ですか。','周期',['ふれはば','ふりこの長さ','おもりの重さ'],['重さを変えても、結果は変わりません。','重さ以外の条件を同じにしたときです。'],'重さを変えても周期は変わらないことが確かめられます。');
  add('pendulum','standard','周期が2秒のふりこは、10往復するのに何秒かかりますか。','20',['2','5','200'],['1往復が2秒です。','2 × 10 を計算しましょう。'],'2 × 10 = 20（秒）かかります。',null,true);
  add('pendulum','standard','時計のふりこの周期を短くするには、どうすればよいですか。','ふりこを短くする',['おもりを重くする','ふれはばを大きくする','おもりを軽くする'],['周期を変えるのは長さです。','短いほど速くゆれます。'],'周期を短くするにはふりこの長さを短くします。');

  add('pendulum','advanced','1往復に2秒かかるふりこをさらに1往復が1秒になるようにするには、どうすればよいですか。','ふりこを短くする',['おもりを軽くする','ふれはばを小さくする','おもりを重くする'],['周期を変えるのは長さだけです。','周期を短くしたいときは長さを短くします。'],'周期を短くするには長さを短くします。重さやふれはばでは変わりません。');
  add('pendulum','advanced','ふりこの周期を2倍にしたいとき、ふりこの長さはおよそ何倍にすればよいですか。','4倍',['2倍','8倍','16倍'],['周期は長さの2乗根に関係します。','長さを4倍にすると周期は2倍になります。'],'周期は長さの平方根に比例するので、長さを4倍にすると周期は2倍になります。');
  add('pendulum','advanced','10往復の時間をはかる実験を3回行い18秒・19秒・20秒でした。10往復の時間の平均は何秒ですか。','19',['18','20','57'],['3つの合計を回数でわります。','（18＋19＋20）÷ 3です。'],'平均は（18 + 19 + 20）÷ 3 = 19（秒）です。',null,true);
  add('pendulum','advanced','ふりこの周期を調べる実験で10往復の時間を何度もはかって平均を求めるのはなぜですか。','はかり方のずれを小さくするため',['おもりを重くするため','ふれはばを大きくするため','長さを短くするため'],['人がストップウォッチを押すときにずれが出ます。','1回だけだと誤差が大きいです。'],'時間のはかりまちがいは、何度かはかって平均することで小さくなります。');
  add('pendulum','advanced','ふりこの長さが1mのふりこと4mのふりこでは、周期はどちらが長いですか。','4mのふりこ',['1mのふりこ','同じ','どちらともいえない'],['長いほど周期が長くなります。','4mのほうが長いです。'],'ふりこの長さが長いほど周期が長いので、4mのふりこのほうが長くなります。', {"kind":"pendulum","panels":[{"mode":"compare","length":1,"unit":"m"},{"mode":"compare","length":4,"unit":"m"}],"caption":"糸の長さを比べる図。周期は示していない","study":true});
  add('pendulum','advanced','おもりを軽くしてもふりこの周期が変わらないのは、なぜですか。','重さによらず同じ長さなら同じようにふれるから',['空気がないから','おもりが重いほどおそくなるから','おもりが軽いほど速くなるから'],['実験の結果からわかります。','周期は長さだけで決まります。'],'ふりこの周期は長さだけで決まりおもりの重さには関係しないという結果になっています。');
  add('pendulum','advanced','ふりこの実験でおもりを糸の下の方にずらして使うと、周期が変わるのはなぜですか。','ふりこの長さが変わるから',['おもりの重さが変わるから','ふれはばが変わるから','空気が少なくなるから'],['ふりこの長さは支点からおもりの中心までです。','おもりの位置を下げると長くなります。'],'おもりの位置が変わると、ふりこの長さが変わるので、周期も変わります。', {"kind":"pendulum","panels":[{"mode":"sliding"}],"caption":"糸の下の方におもりを置いた模式図。もとの位置は示していない","study":true});
  add('pendulum','advanced','ふりこの周期とふれはばの関係を調べる実験で変えてはいけない条件はどれですか。','ふりこの長さ',['ふれはば','周期','ふれる方向'],['調べたい条件だけを変えます。','ふれはば以外は同じにします。'],'調べたい条件以外は同じにそろえなくてはいけません。');
  add('pendulum','advanced','ふれはばを10度にしたときと30度にしたときで10往復の時間が同じでした。このことからわかることは何ですか。','周期はふれはばに関係しない',['周期はふれはばが大きいと長くなる','周期はふれはばが大きいと短くなる','おもりが重いと周期が長くなる'],['10往復の時間が同じです。','ふれはばを変えても結果が同じです。'],'ふれはばを変えても10往復の時間が同じなので、周期はふれはばに関係しないことがわかります。');
  add('pendulum','advanced','ふりこが1往復するのに0.5秒かかります。このふりこが30秒間にふれる回数（往復）は何回ですか。','60',['15','30','120'],['30秒を周期でわります。','30 ÷ 0.5 を計算しましょう。'],'往復の回数は 30 ÷ 0.5 = 60（回）です。',null,true);
  add('pendulum','advanced','長さ25cmと100cmのふりこがあります。周期が短いのはどちらですか。','25cmのふりこ',['100cmのふりこ','同じ','おもりの重さによる'],['短いほど周期が短いです。','長さの短いほうが速くゆれます。'],'ふりこの長さが短いほうが周期が短いので、25cmのふりこのほうが短くなります。', {"kind":"pendulum","panels":[{"mode":"compare","length":25,"unit":"cm"},{"mode":"compare","length":100,"unit":"cm"}],"caption":"糸の長さを比べる図。周期は示していない","study":true});
  add('pendulum','advanced','ふりこを使った実験で結果が信頼できるようにするには、どんなことに気をつければよいですか。','調べる条件だけを変え何回もはかる',['できるだけ多くの条件を同時に変える','1回だけはかる','感覚で決める'],['条件をそろえることが大切です。','何度もはかって平均します。'],'条件制御（調べる条件だけを変える）とくり返しの測定が大切です。');

  // ---- 電磁石：基礎9・標準15・発展12 ----
  add('electromagnet','basic','コイルに鉄心を入れて、電流を流すと磁石になるものを何といいますか。','電磁石',['永久磁石','電池','かん電池'],['電流が流れているときだけ磁石になります。','鉄しんにコイルを巻いたものです。'],'コイルに電流を流して磁石のはたらきを持たせたものを電磁石といいます。');
  add('electromagnet','basic','電磁石はどんなときに磁石のはたらきをしますか。','電流が流れているとき',['いつでも','電流が流れていないとき','かん電池をはずしたとき'],['電流を切ると、磁石のはたらきもなくなります。','スイッチを入れたときだけです。'],'電磁石は電流が流れているときだけ磁石になり電流を切ると磁石のはたらきはなくなります。');
  add('electromagnet','basic','電磁石の鉄しんには何を使いますか。','鉄',['プラスチック','ゴム','ガラス'],['磁石につくものです。','くぎのようなものです。'],'電磁石の鉄しんには鉄のくぎや棒を使います。');
  add('electromagnet','basic','磁石の両はしにあって、N極やS極とよばれる部分のことを何といいますか。','極',['面','点','線'],['N極とS極があります。','磁石の両はしです。'],'電磁石にも永久磁石と同じようにN極とS極があります。');
  add('electromagnet','basic','電磁石に流す電流の向きを反対にすると、N極とS極はどうなりますか。','入れかわる',['変わらない','なくなる','両方N極になる'],['かん電池の向きを反対にしたときです。','電流の向きに関係します。'],'電流の向きを反対にすると、電磁石のN極とS極が入れかわります。');
  add('electromagnet','basic','電磁石をつよくするには、コイルの巻き数をどうしますか。','ふやす',['へらす','変えない','なくす'],['巻き数が多いほど強い磁石になります。','もっと巻きます。'],'コイルの巻き数を多くすると、電磁石は強くなります。');
  add('electromagnet','basic','電磁石をつよくするには、電流の大きさをどうしますか。','大きくする',['小さくする','変えない','なくす'],['かん電池を直列につなぐと大きくなります。','電流が大きいほど強くなります。'],'電流を大きくすると、電磁石は強くなります。');
  add('electromagnet','basic','電磁石のコイルの中に鉄しんを入れないと磁石の強さはどうなりますか。','弱くなる',['強くなる','変わらない','なくなる'],['鉄しんは磁石の力を強くします。','鉄しんがあるほうが強いです。'],'鉄しんがあると磁石の力は強くなりないと弱くなります。');
  add('electromagnet','basic','電磁石にくっつくものは、次のうちどれですか。','鉄のくぎ',['アルミニウムのかん','銅のはり金','ガラスのびん'],['磁石につくものは鉄などです。','アルミニウムや銅にはつきません。'],'電磁石は鉄のくぎにはつきますが、アルミニウム・銅・ガラスにはつきません。');

  add('electromagnet','standard','電磁石の強さと巻き数の関係を調べるとき、変える条件はどれですか。','コイルの巻き数',['電流の大きさ','鉄しんの太さ','導線の色'],['調べたいものだけを変えます。','巻き数を変えます。'],'調べたいことが巻き数なので、変える条件はコイルの巻き数ほかは同じにします。');
  add('electromagnet','standard','電磁石の強さと電流の大きさの関係を調べるとき、同じにする条件はどれですか。','コイルの巻き数と鉄しん',['電流の大きさ','かん電池の数','何も同じにしない'],['変えるのは電流の大きさだけです。','巻き数や鉄しんはそろえます。'],'電流の大きさだけを変えて、巻き数や鉄しんは同じにして調べます。');
  add('electromagnet','standard','かん電池を2個直列につなぐと、1個のときにくらべて電流の大きさはどうなりますか。','大きくなる',['小さくなる','変わらない','なくなる'],['直列につなぐと、電流が大きくなります。','電池が2個だと力が強くなります。'],'かん電池を直列につなぐと、電流が大きくなり電磁石も強くなります。', {"kind":"circuit","panels":[{"layout":"row","device":"coil"}],"caption":"電池二つと鉄しんのあるコイルの回路。電流の大きさは示していない","study":true});
  add('electromagnet','standard','かん電池を2個へい列につなぐと、1個のときにくらべて電流の大きさはどうなりますか。','変わらない',['2倍になる','半分になる','なくなる'],['へい列つなぎは電池が長持ちします。','電流の大きさは1個のときと変わりません。'],'へい列につなぐと電流の大きさは1個のときと同じですが、電池が長持ちします。', {"kind":"circuit","panels":[{"layout":"branches","device":"coil"}],"caption":"電池二つと鉄しんのあるコイルの回路。電流の大きさは示していない","study":true});
  add('electromagnet','standard','巻き数が50回のコイルと100回のコイルでは、電磁石が強いのはどちらですか（鉄しん・電流は同じ）。','100回のコイル',['50回のコイル','同じ','どちらともいえない'],['巻き数が多いほうが強いです。','100回のほうが多く巻いてあります。'],'巻き数が多いほど電磁石は強くなるので、100回のコイルのほうが強いです。', {"kind":"circuit","panels":[{"layout":"single","device":"coil","turns":50},{"layout":"single","device":"coil","turns":100}],"caption":"巻き数を比べる。コイルの線は省略して描いている","study":true});
  add('electromagnet','standard','電磁石のN極とS極を調べるには、何を使えばよいですか。','方位磁針',['温度計','ものさし','てんびん'],['針が引きつけられたり反発したりします。','N極が北を指す道具です。'],'方位磁針の針の向きを見て、電磁石のN極とS極を調べます。');
  add('electromagnet','standard','電磁石の強さは何で比べますか。','引きつけるクリップの数',['電池の色','コイルの太さ','鉄しんの長さ'],['つくクリップの数をかぞえます。','たくさん引きつけるほど強いです。'],'電磁石の強さは引きつけるクリップ（鉄）の数で比べることができます。', {"kind":"circuit","panels":[{"layout":"single","device":"coil","clipBox":true}],"caption":"コイルのそばにクリップの箱。引きつけた結果は示していない","study":true});
  add('electromagnet','standard','電磁石の鉄しんをのぞくと、引きつけるクリップの数はどうなりますか。','へる',['ふえる','変わらない','ちょうど2倍になる'],['鉄しんがあるほうが強いです。','鉄しんをぬくと弱くなります。'],'鉄しんがなくなると、電磁石は弱くなりクリップがつきにくくなります。');
  add('electromagnet','standard','電磁石を永久磁石とくらべたとき、電磁石だけの特長はどれですか。','電流を切るとはたらきがなくなる',['鉄を引きつける','N極とS極がある','コイルがない'],['スイッチで入り切りできます。','電流が流れているときだけ磁石になります。'],'電磁石は電流を流す・切ることで磁石のはたらきを入り切りできます。');
  add('electromagnet','standard','電磁石の極を入れかえたいとき、どうすればよいですか。','かん電池の向きを反対にする',['鉄しんを太くする','コイルの巻き数をふやす','導線を長くする'],['電流の向きを反対にします。','かん電池をひっくり返します。'],'電流の向きを反対にすると、N極とS極が入れかわります。');
  add('electromagnet','standard','電磁石を使ったものはどれですか。','モーター',['てんびん','温度計','ものさし'],['電流で回るものです。','回る力を出すものです。'],'モーターには電磁石が使われていて、電流で回転します。');
  add('electromagnet','standard','電磁石が永久磁石のようにいつも磁石になっていないのは、なぜですか。','電流が流れているときだけ磁石になるから',['鉄しんがないから','コイルが細いから','電池がないから'],['電流と関係があります。','電流を切ると磁石でなくなります。'],'電磁石は電流が流れているときだけ磁石のはたらきを持ちます。');
  add('electromagnet','standard','電磁石を使ったおもちゃのクレーンは、どんなことに役立ちますか。','鉄のものを持ち上げて、電流を切ってはなす',['電池を温める','ものを切る','水をくみ上げる'],['スイッチを切ると、ものがはなれます。','電磁石の入り切りを使います。'],'電磁石の入り切りを使って、鉄のものを持ち上げはなすことができます。');
  add('electromagnet','standard','コイルに電流を流したとき、鉄しんの先にできる極は、何で決まりますか。','電流の向き',['コイルの色','鉄しんの長さ','電池のメーカー'],['かん電池の向きを変えると変わります。','電流の向きと巻き方が関係します。'],'電磁石の極は電流の向きによって決まります。');

  add('electromagnet','advanced','電磁石の強さと巻き数の関係を調べる実験で巻き数以外に同じにしなければいけない条件は何ですか。','電流の大きさと鉄しん',['コイルの巻き数','引きつけるクリップの数','かん電池の色'],['変えるのは巻き数だけです。','条件制御が大切です。'],'巻き数だけを変えて、電流の大きさや鉄しんなどは同じにして調べます。');
  add('electromagnet','advanced','電磁石の強さと電流の大きさの関係を調べる実験で電流を大きくするには、どうすればよいですか。','かん電池を直列につなぐ',['かん電池をへい列につなぐ','コイルの巻き数をへらす','鉄しんをぬく'],['電流を大きくするつなぎ方です。','電池を2つつなぎます。'],'かん電池を直列につなぐと、電流が大きくなります。');
  add('electromagnet','advanced','コイルの巻き数を2倍にして、かん電池を1個から2個の直列にしました。電磁石の強さはどうなりますか。','強くなる',['弱くなる','変わらない','なくなる'],['どちらも強くする条件です。','強くする条件が2つ重なっています。'],'巻き数を多くすることも電流を大きくすることも電磁石を強くします。');
  add('electromagnet','advanced','電磁石を2つ作りました。一方は巻き数100回もう一方は巻き数200回でほかは同じです。クリップをよりたくさん引きつけるのはどちらですか。','200回のほう',['100回のほう','同じ','どちらともいえない'],['巻き数が多いほうが強いです。','200回のほうが多いです。'],'巻き数が多いほど電磁石は強くより多くのクリップを引きつけます。', {"kind":"circuit","panels":[{"layout":"single","device":"coil","turns":100},{"layout":"single","device":"coil","turns":200}],"caption":"巻き数を比べる。コイルの線は省略して描いている","study":true});
  add('electromagnet','advanced','電磁石の強さが電流の大きさだけに関係すると言えるのは、どんな実験をしたときですか。','巻き数や鉄しんは同じで電流だけを変えた実験',['巻き数と電流を同時に変えた実験','1回だけ行った実験','電池の色を変えた実験'],['変える条件を1つにします。','ほかの条件を同じにします。'],'電流以外の条件を同じにして、電流だけを変えて比べた実験でないと関係を調べられません。');
  add('electromagnet','advanced','電磁石に電流を長い時間流しつづけると、どんなことが起こりますか。','コイルや電池が熱くなる',['電流が強くなる','磁石が消える','鉄しんが水になる'],['電流が流れると、導線が温まります。','長く流すと危険です。'],'電流を流しつづけると導線や電池が熱くなるので、必要なときだけ流します。');
  add('electromagnet','advanced','電磁石の極を調べるため、方位磁針を電磁石の近くに置いたら、針のN極が電磁石の先に引きつけられました。電磁石の先は何極ですか。','S極',['N極','どちらでもない','極はない'],['磁石はちがう極どうしが引き合います。','N極に引き合うのはS極です。'],'方位磁針のN極が引きつけられたので、電磁石の先はS極です。', {"kind":"circuit","panels":[{"layout":"single","device":"coil","compass":"toward"}],"caption":"方位磁針のN側がコイルの先へ向いた、問題文の状態","study":true});
  add('electromagnet','advanced','電磁石を使って強い力で鉄のかたまりをクレーンで持ち上げるには、どうすればよいですか。','巻き数をふやし電流を大きくする',['巻き数をへらす','電流を小さくする','鉄しんをぬく'],['強くする条件を考えましょう。','巻き数と電流の大きさです。'],'巻き数をふやすことと電流を大きくすることで電磁石を強くできます。');
  add('electromagnet','advanced','モーターに使われている電磁石は、電流の向きを切りかえることで何ができますか。','回りつづける',['止まる','熱くなる','光る'],['電磁石の極が入れかわると、動きつづけます。','極が入れかわると、引き合いや反発が変わります。'],'電流の向きを切りかえて、電磁石の極を入れかえることでモーターは回りつづけます。');
  add('electromagnet','advanced','かん電池1個で巻き数50回のとき、クリップが5個つきました。巻き数100回にすると、クリップはどうなりますか（ほかは同じ）。','5個より多くなる',['5個より少なくなる','5個のまま','0個になる'],['巻き数が多いと強くなります。','巻き数が2倍になっています。'],'巻き数を多くすると電磁石は強くなるので、つくクリップの数もふえます。', {"kind":"circuit","panels":[{"layout":"single","device":"coil","turns":50},{"layout":"single","device":"coil","turns":100}],"caption":"電池はそれぞれ一つ。巻き数を比べる模式図","study":true});
  add('electromagnet','advanced','電磁石に使う導線を太さが同じで巻き数だけが多いものにするとき、必要なことは何ですか。','導線をふやして長くする',['導線を細くする','導線を短くする','導線を折る'],['巻き数が多いと使う導線が長くなります。','巻き数を多くするために導線を長く使います。'],'巻き数を多くするには、導線を長くします。');
  add('electromagnet','advanced','電磁石と永久磁石のちがいを次から選びましょう。','電磁石は電流を流したときだけ磁石になる',['電磁石にはN極だけがある','永久磁石にはS極だけがある','どちらも電流が必要'],['電流の入り切りを使えるのが電磁石です。','永久磁石はいつも磁石です。'],'電磁石は電流を流したときだけ磁石になり永久磁石はいつも磁石のはたらきを持っています。');

  // ---- 実験の方法と考え方：基礎9・標準15・発展12 ----
  add('method','basic','実験で調べたい条件だけを変えほかの条件は同じにして比べることを何といいますか。','条件をそろえる',['条件をふやす','条件を変えない','結果を予想する'],['調べたいことだけを変えます。','ほかの条件は同じにします。'],'調べたい条件だけを変えほかは同じにして比べると、原因がはっきりします。');
  add('method','basic','実験で「変える条件」とはどんなものですか。','調べたいこと',['同じにする条件','結果','道具'],['比べたいものが変える条件です。','何がちがいを生むのか調べたいことです。'],'変える条件は調べたいことそのものです。');
  add('method','basic','実験で「同じにする条件」とは、どんなものですか。','調べたいこと以外の条件',['調べたいこと','実験の結果','道具の名前'],['変える条件のほかのものです。','ほかの条件はそろえます。'],'同じにする条件は調べたいこと以外の条件のことです。');
  add('method','basic','実験の結果をあとで見返すためにどうしておくとよいですか。','記録しておく',['すぐ忘れる','口だけで言う','書かない'],['数字や気づいたことを書きます。','あとで見ると役立ちます。'],'実験の結果は表やメモに記録しておくと、あとで見返せます。');
  add('method','basic','実験の結果を表にまとめるのはどんな利点がありますか。','結果が比べやすくなる',['答えが変わる','実験しなくてよい','結果が消える'],['数や文字を整理できます。','見やすくなります。'],'表にまとめると、結果が整理されて比べやすくなります。');
  add('method','basic','実験を安全に行うためにさいしょにすることは何ですか。','先生や教科書の説明をよく読む',['すぐに始める','火を大きくする','道具をなげる'],['やり方を確認します。','注意点を知っておきましょう。'],'実験の前にやり方と注意点をよく確認して、安全に行います。');
  add('method','basic','実験で火を使うとき、まず気をつけることは何ですか。','燃えやすいものを近くに置かない',['しゃがんで見る','窓を全部しめる','手でさわる'],['やけどや火事に注意します。','机の上をかたづけておきます。'],'火を使うときは近くに燃えやすいものを置かないなど安全に注意します。');
  add('method','basic','実験や観察をするとき、目で見るだけでなくどんなこともするとよいですか。','記録する',['何もしない','予想を言わない','かたづけない'],['数字や絵文で残します。','あとで見返すためです。'],'見たことを数・絵・文で記録しておくと、結果を比べたり見返したりできます。');
  add('method','basic','実験の前に結果を予想することを何といいますか。','予想',['まとめ','考察','計算'],['実験をする前に考えます。','こうなるだろうと考えることです。'],'実験の前に結果がどうなるかを考えることを予想といいます。');

  add('method','standard','「ふりこの周期とおもりの重さの関係」を調べるとき、変える条件はどれですか。','おもりの重さ',['ふりこの長さ','ふれはば','周期'],['調べたいのは重さとの関係です。','重さだけを変えます。'],'調べたいことが重さなので、おもりの重さを変えて、ほかは同じにします。');
  add('method','standard','「ふりこの周期とおもりの重さの関係」を調べるとき、同じにする条件はどれですか。','ふりこの長さとふれはば',['おもりの重さ','周期','何もない'],['重さ以外をそろえます。','長さとふれはばは変えません。'],'重さ以外の長さやふれはばは、同じにそろえます。');
  add('method','standard','「ものが水にとける量と水の温度の関係」を調べるとき、変える条件はどれですか。','水の温度',['水の量','とかすものの種類','ビーカーの形'],['調べたいことだけを変えます。','温度を変えて調べます。'],'調べたいことが温度なので、水の温度を変え水の量やとかすものは同じにします。');
  add('method','standard','「ものが水にとける量と水の温度の関係」を調べるとき、同じにする条件はどれですか。','水の量ととかすものの種類',['水の温度','結果','とけたかどうか'],['温度以外の条件です。','量や種類をそろえます。'],'水の量・とかすものの種類など温度以外の条件を同じにします。');
  add('method','standard','植物の発芽に空気が必要かを調べるとき、変える条件はどれですか。','空気の有無',['水の量','温度','日光'],['調べたいことだけを変えます。','空気があるかないかです。'],'調べたいことが空気なので、空気の有無を変え水・温度などは同じにします。');
  add('method','standard','実験の結果を表にまとめたら、ある条件でだけ結果がちがっていました。このちがいは何によるものと考えられますか。','変えた条件',['同じにした条件','道具','実験した日'],['変えた条件によって結果がちがうと考えます。','条件が同じなら、結果も同じはずです。'],'ほかの条件が同じなので、結果のちがいは変えた条件によると考えられます。');
  add('method','standard','「予想」と「結果」がちがっていたとき、どうしますか。','なぜかを考える',['結果を書きかえる','もう一度予想しない','実験をやめる'],['結果は正しく記録します。','わけを考えることが大切です。'],'予想とちがう結果が出たら、なぜかを考えもう一度確かめるなどします。');
  add('method','standard','実験でなるべく正確な結果を得るためにできることは何ですか。','何回か行って平均する',['1回だけ行う','感覚で決める','結果を予想だけで決める'],['何回かやってみると、ずれが分かります。','平均を出します。'],'何回か行って平均を出すと、はかり方のずれによる影響を小さくできます。');
  add('method','standard','ある植物を日当たりのよい所と日かげで育てたら、日当たりのよい所のほうがよく育ちました。ただし、土や水の量もちがっていました。この実験の問題点は何ですか。','日光以外の条件もちがっている',['日光を当てたこと','植物を使ったこと','育てた日数'],['調べたいこと以外の条件がそろっていません。','ほかの条件も変わっています。'],'日光だけを変えて調べるには、水や土などの条件をそろえる必要があります。');
  add('method','standard','実験器具をていねいにあつかうために気をつけることは何ですか。','使い方を確かめて使う',['ていねいに使わない','水でぬらしたまま放置する','ふざけて使う'],['安全に使うために必要です。','器具の正しい使い方を守ります。'],'実験器具の使い方を確認して、安全に使います。');
  add('method','standard','メスシリンダーで液体の体積をはかるとき、目の高さをどうしますか。','液面と同じ高さにする',['上から見る','下から見る','どこでもよい'],['読み取りまちがいをふせぎます。','真横から目盛りを読みます。'],'メスシリンダーの目盛りは、液面と目の高さを同じにして読みます。', {"kind":"apparatus","panels":[{"tool":"cylinder","eyes":["ア","イ","ウ"]}],"caption":"液面を見る三つの目の位置。正しい位置は示していない","study":true});
  add('method','standard','実験の結果をグラフにすると、どんな利点がありますか。','変化のようすがひと目でわかる',['結果が変わる','実験をしなくてよい','数字が消える'],['線や棒で表します。','変化の特ちょうを見つけやすいです。'],'グラフにすると、変化のようすや特ちょうがひと目でわかります。');
  add('method','standard','水の温度とミョウバンのとける量の実験でグラフの横軸にするのは、ふつうどちらですか。','水の温度',['とけた量','ミョウバンの色','ビーカーの数'],['変える条件を横軸にします。','結果を縦軸にします。'],'ふつう変える条件（温度）を横軸結果（とけた量）を縦軸にします。');
  add('method','standard','ある実験で結果の数字がほかとくらべて極端にちがっていました。まず何をしますか。','まちがいがないかやり方を確かめる',['すぐ捨てる','そのまま使う','別の数字に書きかえる'],['はかり方や記録を見直しましょう。','原因を調べます。'],'極端な結果が出たら、はかり方や記録にまちがいがないかを確かめます。');
  add('method','standard','観察するときにスケッチをかくのはどんな目的ですか。','見たことを正確に残す',['色をぬるため','きれいな絵にするため','先生に見せるため'],['観察の記録の一つです。','細かなところまで残します。'],'スケッチは観察して気づいたことを正確に記録するために行います。');

  add('method','advanced','ふりこの実験で「おもりの重さ」と「ふれはば」を同時に変えてしまいました。この実験の何が問題ですか。','周期のちがいが何によるのかわからない',['時間がかかる','おもりが重い','実験が簡単すぎる'],['調べたい条件が2つ同時に変わっています。','どちらが原因かわかりません。'],'2つの条件を同時に変えると、結果のちがいがどちらによるのか決められません。', {"kind":"pendulum","panels":[{"mode":"amplitude","label":"Ａ","angle":15,"size":16},{"mode":"amplitude","label":"Ｂ","angle":35,"size":26}],"caption":"おもりとふれはばを同時に変えた模式図","study":true});
  add('method','advanced','ふりこの周期を調べるため、ふりこの長さを25cm・50cm・100cm・200cmと変えました。このとき同じにする条件はどれですか。','おもりの重さとふれはば',['ふりこの長さ','周期','何もない'],['変えるのは長さだけです。','それ以外はそろえます。'],'長さ以外の条件（おもりの重さ・ふれはば）は同じにそろえます。', {"kind":"pendulum","panels":[{"mode":"compare","length":25,"unit":"cm"},{"mode":"compare","length":50,"unit":"cm"},{"mode":"compare","length":100,"unit":"cm"},{"mode":"compare","length":200,"unit":"cm"}],"caption":"糸の長さだけを変えた四つのふりこ","study":true});
  add('method','advanced','実験の結果をもとに結論を出すとき、大切なことは何ですか。','実験の結果から言えることだけを述べる',['予想どおりの結論にする','結果に合わせて予想を変える','自分の考えだけを書く'],['結果にもとづくことが大切です。','結果にないことは言いません。'],'結論は実験の結果から言えることだけを書きます。');
  add('method','advanced','1回の実験で出た結果だけで「いつでもこうなる」と決めてしまうのは、なぜよくないですか。','たまたまの結果かもしれないから',['実験が簡単だから','道具が高いから','先生がきらいだから'],['くり返して確かめることが大切です。','何度か行ってみることが大切です。'],'くり返し実験して、同じ結果が出ることを確かめてから結論を出します。');
  add('method','advanced','次の実験で「何が変えた条件か」を答えましょう。「同じ大きさのビーカーに20℃・40℃・60℃の水を100mLずつ入れミョウバンをとかせるだけとかす」','水の温度',['水の量','ビーカーの大きさ','とかすもの'],['値が3つ変わっているものです。','20℃・40℃・60℃です。'],'水の温度が3つに変わっていて、水の量・ビーカー・とかすものは同じです。', {"kind":"apparatus","panels":[{"tool":"beaker","notes":["20℃","100mL"],"solute":{"label":"ミョウバン"},"temperature":20},{"tool":"beaker","notes":["40℃","100mL"],"solute":{"label":"ミョウバン"},"temperature":40},{"tool":"beaker","notes":["60℃","100mL"],"solute":{"label":"ミョウバン"},"temperature":60}],"caption":"同じ量の水を使う実験。とけた量は示していない","study":true});
  add('method','advanced','表の結果をグラフにするとき、グラフの横軸・縦軸にそれぞれ何を取るかを決めるときの基本は何ですか。','変える条件を横軸結果を縦軸にする',['結果を横軸変える条件を縦軸にする','どちらも結果にする','決まりはない'],['条件が横結果はたてじくです。','何によって結果が変わったかを見ます。'],'ふつう変えた条件を横軸その結果を縦軸にとります。', {"kind":"graph","values":[],"labels":[],"science":true,"blankAxes":true,"caption":"グラフの空のわく。軸の名前と結果は示していない","study":true});
  add('method','advanced','実験を「くり返して」結果の平均をとるのは、何を小さくするためですか。','はかるときのずれ（誤差）',['実験の時間','道具の数','予想'],['何回かはかると、ずれが目立たなくなります。','人がはかるときにずれが出ます。'],'くり返して平均をとると、はかるときのずれ（誤差）が小さくなります。');
  add('method','advanced','2つのグループが同じ実験をしたところ、結果が少しちがっていました。考えられる理由は何ですか。','はかり方や条件に少しのちがいがあった',['実験は意味がない','先生がまちがえた','どちらかがうそをついた'],['はかり方のちがいなどがあります。','完全に同じ条件にするのはむずかしいです。'],'はかり方や条件に小さなちがいがあって、結果に少しのずれが出ることがあります。');
  add('method','advanced','ものがとける量の実験で水の量を2倍にしたとき、とける量はどうなりますか（温度は同じ）。','およそ2倍になる',['半分になる','変わらない','10倍になる'],['水が2倍なら、とける量もふえます。','水の量に比例します。'],'同じ温度では水の量が2倍になると、とける量もおよそ2倍になります。');
  add('method','advanced','実験で予想がまちがっていたとき、いちばん大切なことは何ですか。','結果をそのまま記録し考え直す',['結果を予想に合わせる','実験をなかったことにする','もう実験しない'],['結果は正直に書きます。','予想を見直します。'],'予想とちがっても、結果をそのまま記録して、考え直すことが大切です。');
  add('method','advanced','実験で「条件を1つだけ変える」というきまりを何といいますか。','条件制御',['条件反射','条件変更','条件追加'],['調べたい条件以外を同じにすることです。','比べるための基本の考え方です。'],'調べたい条件だけを変えて、ほかを同じにする考え方を条件制御といいます。');
  add('method','advanced','ふりこ・電磁石・もののとけ方の実験に共通する大切な考え方はどれですか。','調べたい条件だけを変えほかは同じにする',['すべての条件を同時に変える','結果を予想だけで決める','1回だけ行う'],['どの実験でも使います。','原因をはっきりさせるための方法です。'],'どの実験でも条件を1つだけ変えほかを同じにして比べることが基本です。');


  add('pendulum','standard','ふりこの長さが50cmのとき、10往復の時間は14秒でした。ふりこの長さを100cmにすると、10往復の時間はどうなりますか。','14秒より長くなる',['14秒より短くなる','14秒のまま','0秒になる'],['長いほど周期が長くなります。','長さが2倍になっています。'],'ふりこの長さを長くすると周期が長くなるので、10往復の時間も14秒より長くなります。');
  add('electromagnet','standard','電磁石に電流を流すとき、スイッチを入れる前に確かめることは何ですか。','導線がしっかりつながっているか',['導線を長くしたか','電池を温めたか','鉄しんを太くしたか'],['つなぎ方をチェックします。','電流が流れる道すじが大切です。'],'電流が流れる道すじが切れていないかつなぎ方を確かめてからスイッチを入れます。');
